namespace sv_46e6b970e4524a2e973344e903d7d090.Models;

public sealed class Recipe
{
    public int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public int PrepTimeMinutes { get; init; }
}

using sv_46e6b970e4524a2e973344e903d7d090.Models;

namespace sv_46e6b970e4524a2e973344e903d7d090.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> _data = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic Italian pizza with tomato, mozzarella, and basil.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Pasta Carbonara", Description = "Creamy Roman pasta with eggs, pecorino, guanciale, and black pepper.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-flavored dessert with mascarpone and cocoa.", PrepTimeMinutes = 45 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Tacos al Pastor", Description = "Marinated pork tacos with pineapple, cilantro, and onion.", PrepTimeMinutes = 40 },
            new() { Id = 5, Title = "Guacamole", Description = "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", PrepTimeMinutes = 10 },
            new() { Id = 6, Title = "Churros", Description = "Fried dough pastry coated in cinnamon sugar, served with chocolate sauce.", PrepTimeMinutes = 35 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Pad Thai", Description = "Stir-fried rice noodles with shrimp, peanuts, bean sprouts, and tamarind sauce.", PrepTimeMinutes = 30 },
            new() { Id = 8, Title = "Green Curry", Description = "Aromatic coconut curry with vegetables, Thai basil, and green chili paste.", PrepTimeMinutes = 35 },
            new() { Id = 9, Title = "Mango Sticky Rice", Description = "Sweet glutinous rice topped with fresh mango and coconut cream.", PrepTimeMinutes = 50 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (_data.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_46e6b970e4524a2e973344e903d7d090.Models
@using sv_46e6b970e4524a2e973344e903d7d090.Services
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav class="mb-3" aria-label="Cuisine selection">
    <a href="/recipes/1?sort=@Sort" class="btn btn-outline-primary me-2 @(CuisineId == 1 ? "active" : "")">Italian</a>
    <a href="/recipes/2?sort=@Sort" class="btn btn-outline-primary me-2 @(CuisineId == 2 ? "active" : "")">Mexican</a>
    <a href="/recipes/3?sort=@Sort" class="btn btn-outline-primary @(CuisineId == 3 ? "active" : "")">Thai</a>
</nav>

<div class="mb-3">
    <label class="form-label fw-semibold me-2">Sort by:</label>
    <a href="/recipes/@CuisineId?sort=newest" class="btn btn-sm @(Sort == "newest" ? "btn-secondary" : "btn-outline-secondary") me-1">Newest</a>
    <a href="/recipes/@CuisineId?sort=popular" class="btn btn-sm @(Sort == "popular" ? "btn-secondary" : "btn-outline-secondary")">Popular</a>
</div>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center" role="alert">
        <span class="me-auto">@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _errorMessage is null)
{
    <p><em>Loading recipes…</em></p>
}
else if (_recipes is not null)
{
    @if (_isRefreshing)
    {
        <div class="text-muted mb-2"><small>Refreshing…</small></div>
    }

    <div class="row">
        @foreach (var recipe in GetSortedRecipes())
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <span class="badge bg-info">@recipe.PrepTimeMinutes min prep</span>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;
    private readonly CancellationTokenSource _disposeCts = new();

    protected override async Task OnParametersSetAsync()
    {
        // Only reload when the cuisine actually changes.
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load.
        await CancelPendingLoadAsync();

        _errorMessage = null;
        _isRefreshing = _recipes is not null;

        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
        var cancellationToken = _loadCts.Token;
        var cuisineId = CuisineId;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(cuisineId, cancellationToken);
            _recipes = result;
            _loadedCuisineId = cuisineId;
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            // Load was intentionally cancelled — nothing to do.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private IEnumerable<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return Enumerable.Empty<Recipe>();

        return Sort?.ToLowerInvariant() switch
        {
            "popular" => _recipes.OrderByDescending(r => r.Id),
            _ => _recipes.OrderBy(r => r.Id),
        };
    }

    private async Task RetryAsync()
    {
        _errorMessage = null;
        await LoadRecipesAsync();
    }

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Dispose();
    }
}

